/****************************************************************************
 * app/home_scense/face_gate.cc
 *
 * Frontal-face gated Doubao voice control (approach A: fully automatic).
 *
 * Detection core (anchors / decode / NMS / frontal geometry / tflite init /
 * MJPEG->128x128 float pre-process) is reused verbatim from
 * apps/examples/face_detection; the LCD preview path (RGB565 buffer, fb_*,
 * overlay/draw, fonts, PPM loader, CLI main) is intentionally dropped — this
 * module only computes "is a frontal face present" and drives the voice
 * state machine.  Runs in its own low-priority thread and never calls LVGL.
 ****************************************************************************/

#include <nuttx/config.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cerrno>
#include <cmath>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <time.h>
#include <sys/ioctl.h>

#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_log.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/system_setup.h"
#include "tensorflow/lite/schema/schema_generated.h"

#include "face_detect_model_data.inc"
#include "tjpgd.h"

#include "face_gate.h"
#include "doubao/doubao_voice.h"

/****************************************************************************
 * Tunables (Kconfig with safe fallbacks)
 ****************************************************************************/

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_ARENA_SIZE
#  define TENSOR_ARENA_SIZE CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_ARENA_SIZE
#else
#  define TENSOR_ARENA_SIZE (384 * 1024)
#endif

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_PERIOD_MS
#  define GATE_PERIOD_MS CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_PERIOD_MS
#else
#  define GATE_PERIOD_MS 300
#endif

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_ON_FRAMES
#  define GATE_ON_FRAMES CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_ON_FRAMES
#else
#  define GATE_ON_FRAMES 3
#endif

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_OFF_FRAMES
#  define GATE_OFF_FRAMES CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_OFF_FRAMES
#else
#  define GATE_OFF_FRAMES 5
#endif

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_MIN_REC_MS
#  define GATE_MIN_REC_MS CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_MIN_REC_MS
#else
#  define GATE_MIN_REC_MS 1500
#endif

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_STACKSIZE
#  define GATE_STACKSIZE CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_STACKSIZE
#else
#  define GATE_STACKSIZE 16384
#endif

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_PRIORITY
#  define GATE_PRIORITY CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_PRIORITY
#else
#  define GATE_PRIORITY 90       /* below UI (100) so the UI never starves */
#endif

#ifndef FACE_ROTATE
#  define FACE_ROTATE 270         /* match the standalone example default */
#endif

/****************************************************************************
 * BlazeFace geometry (verbatim from the face_detection example)
 ****************************************************************************/

#define IN_W          128
#define IN_H          128
#define IN_CH         3
#define NUM_ANCHORS   896
#define NUM_COORDS    16
#define NUM_KP        6
#define BOX_SCALE     128.0f

#define SCORE_THRESH  0.6f
#define NMS_IOU       0.30f
#define MAX_CAND      128
#define MAX_DET       16
#define ROLL_THRESH   0.40f
#define YAW_THRESH    0.35f

#define KP_EYE0 0
#define KP_EYE1 1
#define KP_NOSE 2
#define KP_MOUTH 3

#define VIDEO_DEV_PATH "/dev/video"
#define CAM_WIDTH      320
#define CAM_HEIGHT     240

#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_BUFS
#  define CAM_BUF_COUNT CONFIG_LVX_USE_DEMO_CONTEST2026_106_FACE_GATE_BUFS
#else
#  define CAM_BUF_COUNT 3
#endif

/****************************************************************************
 * Private types / data
 ****************************************************************************/

struct v_buffer
{
  uint8_t *start;
  uint32_t length;
};

struct detection_s
{
  float score;
  float xmin, ymin, xmax, ymax;
  float kp[NUM_KP][2];
  int   frontal;
};

static uint8_t  g_tensor_arena[TENSOR_ARENA_SIZE] __attribute__((aligned(16)));
static float    g_inbuf[IN_W * IN_H * IN_CH];
static uint8_t  g_framecopy[CAM_WIDTH * CAM_HEIGHT * 2];
static float    g_anchor_cx[NUM_ANCHORS];
static float    g_anchor_cy[NUM_ANCHORS];
static detection_s g_cand[MAX_CAND];
static detection_s g_det[MAX_DET];

/* thread control */

static pthread_t       g_thread;
static volatile bool   g_stop      = false;
static bool            g_started   = false;
static volatile bool   g_present   = false;   /* debounced result for UI */

/****************************************************************************
 * tjpgd callbacks — output only fills the 128x128 float model input
 ****************************************************************************/

struct mjpeg_iodev_s
{
  const uint8_t *data;
  size_t         len;
  size_t         pos;
};

static size_t mjpeg_input(JDEC *jd, uint8_t *buff, size_t nbyte)
{
  struct mjpeg_iodev_s *io = (struct mjpeg_iodev_s *)jd->device;
  size_t avail = io->len - io->pos;
  if (nbyte > avail) nbyte = avail;
  if (buff) memcpy(buff, io->data + io->pos, nbyte);
  io->pos += nbyte;
  return nbyte;
}

static inline float normalise_u8(uint8_t v)
{
  return (float)v / 127.5f - 1.0f;
}

static int mjpeg_output(JDEC *jd, void *bitmap, JRECT *rect)
{
  uint8_t *src = (uint8_t *)bitmap;
  uint32_t x;
  uint32_t y;

  for (y = rect->top; y <= rect->bottom && y < CAM_HEIGHT; y++)
    {
      for (x = rect->left; x <= rect->right && x < CAM_WIDTH; x++)
        {
          uint8_t b = *src++;
          uint8_t g = *src++;
          uint8_t r = *src++;

#if FACE_ROTATE == 90
          int dx = (int)((CAM_HEIGHT - 1 - y) * IN_W / CAM_HEIGHT);
          int dy = (int)(x * IN_H / CAM_WIDTH);
#elif FACE_ROTATE == 180
          int dx = (int)((CAM_WIDTH - 1 - x) * IN_W / CAM_WIDTH);
          int dy = (int)((CAM_HEIGHT - 1 - y) * IN_H / CAM_HEIGHT);
#elif FACE_ROTATE == 270
          int dx = (int)(y * IN_W / CAM_HEIGHT);
          int dy = (int)((CAM_WIDTH - 1 - x) * IN_H / CAM_WIDTH);
#else
          int dx = (int)(x * IN_W / CAM_WIDTH);
          int dy = (int)(y * IN_H / CAM_HEIGHT);
#endif
          if (dx >= IN_W) dx = IN_W - 1;
          if (dy >= IN_H) dy = IN_H - 1;
          if (dx < 0) dx = 0;
          if (dy < 0) dy = 0;
          float *p = &g_inbuf[(dy * IN_W + dx) * IN_CH];
          p[0] = normalise_u8(r);
          p[1] = normalise_u8(g);
          p[2] = normalise_u8(b);
        }

      if (rect->right >= CAM_WIDTH)
        src += (rect->right - CAM_WIDTH + 1) * 3;
    }

  return 1;
}

/****************************************************************************
 * Post-processing (verbatim from the example)
 ****************************************************************************/

static int generate_anchors(void)
{
  static const int strides[4] = {8, 16, 16, 16};
  const int num_layers = 4;
  const float off = 0.5f;
  int count = 0;
  int layer = 0;

  while (layer < num_layers)
    {
      int last = layer;
      int anchors_per_cell = 0;
      while (last < num_layers && strides[last] == strides[layer])
        {
          anchors_per_cell += 2;
          last++;
        }

      int stride = strides[layer];
      int fm_w = (IN_W + stride - 1) / stride;
      int fm_h = (IN_H + stride - 1) / stride;

      for (int y = 0; y < fm_h; y++)
        for (int x = 0; x < fm_w; x++)
          for (int a = 0; a < anchors_per_cell; a++)
            if (count < NUM_ANCHORS)
              {
                g_anchor_cx[count] = ((float)x + off) / (float)fm_w;
                g_anchor_cy[count] = ((float)y + off) / (float)fm_h;
                count++;
              }

      layer = last;
    }

  return count;
}

static inline float sigmoidf(float x)
{
  if (x < -100.0f) x = -100.0f;
  if (x >  100.0f) x =  100.0f;
  return 1.0f / (1.0f + expf(-x));
}

static float iou(const detection_s *a, const detection_s *b)
{
  float x0 = fmaxf(a->xmin, b->xmin);
  float y0 = fmaxf(a->ymin, b->ymin);
  float x1 = fminf(a->xmax, b->xmax);
  float y1 = fminf(a->ymax, b->ymax);
  float iw = fmaxf(0.0f, x1 - x0);
  float ih = fmaxf(0.0f, y1 - y0);
  float inter = iw * ih;
  float ua = (a->xmax - a->xmin) * (a->ymax - a->ymin) +
             (b->xmax - b->xmin) * (b->ymax - b->ymin) - inter;
  return ua > 0.0f ? inter / ua : 0.0f;
}

static int decode_detections(const float *box_t, const float *score_t)
{
  int n = 0;

  for (int i = 0; i < NUM_ANCHORS && n < MAX_CAND; i++)
    {
      float score = sigmoidf(score_t[i]);
      if (score < SCORE_THRESH)
        continue;

      const int base = i * NUM_COORDS;
      float acx = g_anchor_cx[i];
      float acy = g_anchor_cy[i];

      float xc = box_t[base + 0] / BOX_SCALE + acx;
      float yc = box_t[base + 1] / BOX_SCALE + acy;
      float w  = box_t[base + 2] / BOX_SCALE;
      float h  = box_t[base + 3] / BOX_SCALE;

      detection_s *d = &g_cand[n++];
      d->score = score;
      d->xmin = xc - w * 0.5f;
      d->ymin = yc - h * 0.5f;
      d->xmax = xc + w * 0.5f;
      d->ymax = yc + h * 0.5f;
      d->frontal = 0;

      for (int k = 0; k < NUM_KP; k++)
        {
          int o = base + 4 + k * 2;
          d->kp[k][0] = box_t[o + 0] / BOX_SCALE + acx;
          d->kp[k][1] = box_t[o + 1] / BOX_SCALE + acy;
        }
    }

  return n;
}

static int nms(int ncand)
{
  static uint8_t removed[MAX_CAND];
  memset(removed, 0, sizeof(removed));
  int ndet = 0;

  for (int iter = 0; iter < ncand && ndet < MAX_DET; iter++)
    {
      int best = -1;
      float best_score = -1.0f;
      for (int i = 0; i < ncand; i++)
        if (!removed[i] && g_cand[i].score > best_score)
          {
            best_score = g_cand[i].score;
            best = i;
          }

      if (best < 0)
        break;

      removed[best] = 1;
      g_det[ndet++] = g_cand[best];

      for (int i = 0; i < ncand; i++)
        if (!removed[i] && iou(&g_cand[best], &g_cand[i]) > NMS_IOU)
          removed[i] = 1;
    }

  return ndet;
}

static int is_frontal(const detection_s *d)
{
  float e0x = d->kp[KP_EYE0][0], e0y = d->kp[KP_EYE0][1];
  float e1x = d->kp[KP_EYE1][0], e1y = d->kp[KP_EYE1][1];
  float nx  = d->kp[KP_NOSE][0];
  float my  = d->kp[KP_MOUTH][1];

  float dx = e1x - e0x;
  float dy = e1y - e0y;
  float eye_dist = sqrtf(dx * dx + dy * dy);
  if (eye_dist < 1e-4f)
    return 0;

  float eye_mid_x = (e0x + e1x) * 0.5f;
  float eye_mid_y = (e0y + e1y) * 0.5f;
  float roll = fabsf(dy) / eye_dist;
  float yaw  = fabsf(nx - eye_mid_x) / eye_dist;
  float ny   = d->kp[KP_NOSE][1];
  int vertical_ok = (ny > eye_mid_y) && (my > ny);

  return (roll < ROLL_THRESH) && (yaw < YAW_THRESH) && vertical_ok;
}

static int identify_outputs(tflite::MicroInterpreter *interp,
                            TfLiteTensor **box, TfLiteTensor **score)
{
  *box = nullptr;
  *score = nullptr;
  size_t count = interp->outputs_size();

  for (size_t i = 0; i < count; i++)
    {
      TfLiteTensor *t = interp->output(i);
      int last = t->dims->data[t->dims->size - 1];
      if (last == NUM_COORDS) *box = t;
      else if (last == 1)     *score = t;
    }

  return (*box && *score) ? 0 : -1;
}

/****************************************************************************
 * Helpers
 ****************************************************************************/

static uint32_t now_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint32_t)(ts.tv_sec * 1000u + ts.tv_nsec / 1000000u);
}

/****************************************************************************
 * Detection thread
 ****************************************************************************/

static void *face_gate_thread(void *arg)
{
  (void)arg;

  /* ---- TFLite init ---- */

  tflite::InitializeTarget();

  const tflite::Model *model = tflite::GetModel(g_face_detect_model_data);
  if (model->version() != TFLITE_SCHEMA_VERSION)
    {
      printf("[face_gate] model schema mismatch\n");
      return nullptr;
    }

  tflite::MicroMutableOpResolver<14> op_resolver;
  op_resolver.AddConv2D();
  op_resolver.AddDepthwiseConv2D();
  op_resolver.AddMaxPool2D();
  op_resolver.AddAveragePool2D();
  op_resolver.AddAdd();
  op_resolver.AddPad();
  op_resolver.AddReshape();
  op_resolver.AddConcatenation();
  op_resolver.AddLogistic();
  op_resolver.AddQuantize();
  op_resolver.AddDequantize();

  tflite::MicroInterpreter interpreter(model, op_resolver,
                                       g_tensor_arena, TENSOR_ARENA_SIZE);
  if (interpreter.AllocateTensors() != kTfLiteOk)
    {
      printf("[face_gate] AllocateTensors failed (arena too small?)\n");
      return nullptr;
    }

  TfLiteTensor *input = interpreter.input(0);
  TfLiteTensor *box   = nullptr;
  TfLiteTensor *score = nullptr;
  if (identify_outputs(&interpreter, &box, &score) != 0)
    {
      printf("[face_gate] cannot find box+score outputs\n");
      return nullptr;
    }

  generate_anchors();

  /* ---- Camera init (MJPEG, USERPTR) ---- */

  struct v4l2_format fmt;
  struct v4l2_requestbuffers req;
  struct v4l2_buffer buf;
  struct v_buffer *buffers = nullptr;
  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  int fd = -1;
  int ret;

  ret = capture_initialize(VIDEO_DEV_PATH);
  if (ret != 0 && ret != -EEXIST)
    {
      printf("[face_gate] capture_initialize failed: %d\n", ret);
      return nullptr;
    }

  fd = open(VIDEO_DEV_PATH, O_RDWR);
  if (fd < 0)
    {
      printf("[face_gate] open %s failed: %d\n", VIDEO_DEV_PATH, errno);
      return nullptr;
    }

  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = CAM_WIDTH;
  fmt.fmt.pix.height = CAM_HEIGHT;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  fmt.fmt.pix.field = V4L2_FIELD_NONE;
  if (ioctl(fd, VIDIOC_S_FMT, (uintptr_t)&fmt) < 0)
    { printf("[face_gate] S_FMT failed: %d\n", errno); close(fd); return nullptr; }

  if (fmt.fmt.pix.sizeimage == 0)
    fmt.fmt.pix.sizeimage = CAM_WIDTH * CAM_HEIGHT * 2;

  memset(&req, 0, sizeof(req));
  req.count = CAM_BUF_COUNT;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;
  if (ioctl(fd, VIDIOC_REQBUFS, (uintptr_t)&req) < 0)
    { printf("[face_gate] REQBUFS failed: %d\n", errno); close(fd); return nullptr; }

  buffers = (struct v_buffer *)calloc(req.count, sizeof(struct v_buffer));
  if (!buffers)
    { close(fd); return nullptr; }

  for (int i = 0; i < (int)req.count; i++)
    {
      buffers[i].length = fmt.fmt.pix.sizeimage;
      buffers[i].start = (uint8_t *)memalign(64, buffers[i].length);
      if (!buffers[i].start)
        { printf("[face_gate] memalign failed\n"); }

      memset(&buf, 0, sizeof(buf));
      buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_USERPTR;
      buf.index = i;
      buf.m.userptr = (uintptr_t)buffers[i].start;
      buf.length = buffers[i].length;
      ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
    }

  if (ioctl(fd, VIDIOC_STREAMON, (uintptr_t)&type) < 0)
    { printf("[face_gate] STREAMON failed: %d\n", errno); goto cleanup; }

  printf("[face_gate] started (%dx%d MJPEG, %d bufs, rotate=%d)\n",
         CAM_WIDTH, CAM_HEIGHT, CAM_BUF_COUNT, FACE_ROTATE);

  /* ---- Debounce + gate state ---- */

  {
    int  on_cnt = 0;
    int  off_cnt = 0;
    bool stable = false;
    bool prev_stable = false;
    bool armed = false;             /* recording started BY the face gate */
    uint32_t t_start = 0;
    int  dq_fail = 0;

    while (!g_stop)
      {
        uint32_t loop_t0 = now_ms();

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_USERPTR;

        if (ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&buf) < 0)
          {
            if (++dq_fail > 30) { printf("[face_gate] camera lost, exiting\n"); break; }
            usleep(20 * 1000);
            continue;
          }
        dq_fail = 0;

        uint32_t n = buf.bytesused;
        if (n > sizeof(g_framecopy)) n = sizeof(g_framecopy);
        memcpy(g_framecopy, (const void *)buf.m.userptr, n);
        ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);

        int frontal = 0;
        if (n > 1024)
          {
            static uint8_t jdwork[4096];
            JDEC jdec;
            struct mjpeg_iodev_s iodev = { g_framecopy, n, 0 };

            memset(g_inbuf, 0, sizeof(g_inbuf));
            if (jd_prepare(&jdec, mjpeg_input, jdwork, sizeof(jdwork), &iodev)
                == JDR_OK)
              {
                jd_decomp(&jdec, mjpeg_output, 0);

                memcpy(input->data.f, g_inbuf, sizeof(g_inbuf));
                if (interpreter.Invoke() == kTfLiteOk)
                  {
                    int ncand = decode_detections(box->data.f, score->data.f);
                    int ndet = nms(ncand);
                    for (int i = 0; i < ndet; i++)
                      if (is_frontal(&g_det[i])) { frontal = 1; break; }
                  }
              }
          }

        /* debounce */

        if (frontal) { on_cnt++; off_cnt = 0; if (on_cnt >= GATE_ON_FRAMES) stable = true; }
        else         { off_cnt++; on_cnt = 0; if (off_cnt >= GATE_OFF_FRAMES) stable = false; }
        g_present = stable;

        /* gate: rising edge starts, stable-absent (after min-record) stops.
         * Only interact with the IDLE<->RECORDING edges so a manual turn or
         * an in-flight response (CONNECTING/WAITING/PLAYING) is never
         * disturbed.
         */

        doubao_voice_snapshot_t snap;
        doubao_voice_get_snapshot(&snap);

        bool rising = stable && !prev_stable;

        if (rising && !armed && snap.state == DOUBAO_VOICE_IDLE)
          {
            if (doubao_voice_start() == 0) { armed = true; t_start = now_ms(); }
          }
        else if (!stable && armed && snap.state == DOUBAO_VOICE_RECORDING &&
                 (now_ms() - t_start) >= (uint32_t)GATE_MIN_REC_MS)
          {
            doubao_voice_stop();
            armed = false;
          }
        else if (snap.state != DOUBAO_VOICE_IDLE &&
                 snap.state != DOUBAO_VOICE_RECORDING)
          {
