int face_gate_start(void)
{
  if (g_started)
    return 0;

  pthread_attr_t attr;
  struct sched_param param;
  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, GATE_STACKSIZE);
  param.sched_priority = GATE_PRIORITY;
  pthread_attr_setschedparam(&attr, &param);

  g_stop = false;
  int ret = pthread_create(&g_thread, &attr, face_gate_thread, nullptr);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      printf("[face_gate] pthread_create failed: %d\n", ret);
      return -ret;
    }

  pthread_setname_np(g_thread, "face_gate");
  g_started = true;
  return 0;
}

void face_gate_stop(void)
{
  if (!g_started)
    return;
  g_stop = true;
  pthread_join(g_thread, nullptr);
  g_started = false;
}

bool face_gate_present(void)
{
